  1	<!DOCTYPE html>
  2	<html lang="en">
  3	<head>
  4	<meta charset="utf-8">
  5	<meta name="viewport" content="width=device-width, initial-scale=1">
  6	<title>Tetris</title>
  7	<style>
  8	  :root {
  9	    --cell: 28px;
 10	    --bg: #14161c;
 11	    --panel: #1e2129;
 12	    --line: #2a2e38;
 13	    --text: #e8eaf0;
 14	    --muted: #9aa0ad;
 15	  }
 16	  * { box-sizing: border-box; }
 17	  body {
 18	    margin: 0;
 19	    min-height: 100vh;
 20	    display: flex;
 21	    align-items: center;
 22	    justify-content: center;
 23	    background: var(--bg);
 24	    color: var(--text);
 25	    font-family: system-ui, -apple-system, "Segoe UI", sans-serif;
 26	  }
 27	  .game {
 28	    display: flex;
 29	    gap: 20px;
 30	    align-items: flex-start;
 31	    padding: 20px;
 32	  }
 33	  .board-wrap { position: relative; }
 34	  .board {
 35	    display: grid;
 36	    grid-template-columns: repeat(10, var(--cell));
 37	    grid-template-rows: repeat(20, var(--cell));
 38	    gap: 1px;
 39	    padding: 1px;
 40	    background: var(--line);
 41	    border: 2px solid var(--line);
 42	  }
 43	  .cell { background: var(--panel); }
 44	  .cell[data-filled="true"] { box-shadow: inset 0 0 0 2px rgba(255,255,255,0.18); }
 45	  .overlay {
 46	    position: absolute;
 47	    inset: 0;
 48	    display: flex;
 49	    align-items: center;
 50	    justify-content: center;
 51	    background: rgba(0,0,0,0.6);
 52	    font-size: 24px;
 53	    font-weight: 600;
 54	  }
 55	  .side {
 56	    display: flex;
 57	    flex-direction: column;
 58	    gap: 14px;
 59	    min-width: 140px;
 60	  }
 61	  .box {
 62	    background: var(--panel);
 63	    border: 1px solid var(--line);
 64	    padding: 10px 12px;
 65	  }
 66	  .label {
 67	    font-size: 11px;
 68	    text-transform: uppercase;
 69	    letter-spacing: 0.08em;
 70	    color: var(--muted);
 71	  }
 72	  .value { font-size: 22px; font-weight: 600; margin-top: 2px; }
 73	  .next-list { display: flex; flex-direction: column; gap: 10px; margin-top: 8px; }
 74	  .mini {
 75	    display: grid;
 76	    grid-template-columns: repeat(4, 16px);
 77	    grid-template-rows: repeat(2, 16px);
 78	    gap: 1px;
 79	  }
 80	  .mini-cell { background: transparent; }
 81	  button {
 82	    font: inherit;
 83	    color: var(--text);
 84	    background: var(--panel);
 85	    border: 1px solid var(--line);
 86	    padding: 8px 12px;
 87	    cursor: pointer;
 88	  }
 89	  button:hover { border-color: var(--muted); }
 90	  .help { font-size: 12px; color: var(--muted); line-height: 1.6; }
 91	  .p-I { background: #22c7e0; }
 92	  .p-O { background: #f2c511; }
 93	  .p-T { background: #9b4dca; }
 94	  .p-S { background: #3cb44b; }
 95	  .p-Z { background: #e6194b; }
 96	  .p-J { background: #2f6fdf; }
 97	  .p-L { background: #f58231; }
 98	</style>
 99	</head>
100	<body>
101	<div class="game">
102	  <div class="board-wrap">
103	    <div class="board" data-testid="board" id="board"></div>
104	  </div>
105	  <div class="side">
106	    <div class="box">
107	      <div class="label">Score</div>
108	      <div class="value" data-testid="score" id="score">0</div>
109	    </div>
110	    <div class="box">
111	      <div class="label">Level</div>
112	      <div class="value" data-testid="level" id="level">1</div>
113	    </div>
114	    <div class="box">
115	      <div class="label">Lines</div>
116	      <div class="value" data-testid="lines" id="lines">0</div>
117	    </div>
118	    <div class="box">
119	      <div class="label">Next</div>
120	      <div class="next-list" data-testid="next-piece" id="next"></div>
121	    </div>
122	    <button type="button" id="new-game">New game</button>
123	    <div class="help">
124	      ← → move<br>
125	      ↓ soft drop<br>
126	      Space hard drop<br>
127	      ↑ rotate
128	    </div>
129	  </div>
130	</div>
131	
132	<script>
133	(function () {
134	  "use strict";
135	
136	  var ROWS = 20;
137	  var COLS = 10;
138	  var TYPES = ["I", "O", "T", "S", "Z", "J", "L"];
139	  var PREVIEW = 1;
140	  var GRAVITY_MS = 1000;
141	  var LOCK_DELAY_TICKS = 2;   // gravity steps a piece may spend unable to fall
142	  var MAX_LOCK_RESETS = 3;    // times per piece a sideways move or soft drop restarts the delay
143	
144	  // Points for rows cleared at once, times the level. Clearing rows together
145	  // must always beat clearing the same rows one at a time.
146	  var CLEAR_POINTS = [0, 100, 300, 500, 800];
147	  var SOFT_DROP_POINTS = 1;   // per cell moved down by soft drop
148	  var HARD_DROP_POINTS = 2;   // per cell dropped by hard drop
149	
150	  // Each shape is a square matrix; spawn puts its filled cells in rows 0-1.
151	  var SHAPES = {
152	    I: { m: ["....", "IIII", "....", "...."], row: -1, col: 3 },
153	    O: { m: ["OO", "OO"], row: 0, col: 4 },
154	    T: { m: [".T.", "TTT", "..."], row: 0, col: 3 },
155	    S: { m: [".SS", "SS.", "..."], row: 0, col: 3 },
156	    Z: { m: ["ZZ.", ".ZZ", "..."], row: 0, col: 3 },
157	    J: { m: ["J..", "JJJ", "..."], row: 0, col: 3 },
158	    L: { m: ["..L", "LLL", "..."], row: 0, col: 3 }
159	  };
160	
161	  // ---- State ----
162	  var board;        // board[row][col] = "" or piece letter
163	  var current;      // { type, matrix, row, col, lockTicks, lockResets } or null
164	  var next;         // upcoming piece letters, soonest first
165	  var scripted;     // true while `next` comes from a test-supplied queue
166	  var bag = [];
167	  var score, level, lines, status;
168	  var timer = null;
169	
170	  function emptyBoard() {
171	    var b = [];
172	    for (var r = 0; r < ROWS; r++) {
173	      var row = [];
174	      for (var c = 0; c < COLS; c++) row.push("");
175	      b.push(row);
176	    }
177	    return b;
178	  }
179	
180	  function randomType() {
181	    if (bag.length === 0) {
182	      bag = TYPES.slice();
183	      for (var i = bag.length - 1; i > 0; i--) {
184	        var j = Math.floor(Math.random() * (i + 1));
185	        var t = bag[i]; bag[i] = bag[j]; bag[j] = t;
186	      }
187	    }
188	    return bag.pop();
189	  }
190	
191	  function fillPreview() {
192	    if (scripted) return;
193	    while (next.length < PREVIEW) next.push(randomType());
194	  }
195	
196	  function shapeCells(matrix, row, col) {
197	    var cells = [];
198	    for (var r = 0; r < matrix.length; r++) {
199	      for (var c = 0; c < matrix[r].length; c++) {
200	        if (matrix[r][c] !== ".") cells.push([row + r, col + c]);
201	      }
202	    }
203	    return cells;
204	  }
205	
206	  function fits(matrix, row, col) {
207	    var cells = shapeCells(matrix, row, col);
208	    for (var i = 0; i < cells.length; i++) {
209	      var r = cells[i][0], c = cells[i][1];
210	      if (r < 0 || r >= ROWS || c < 0 || c >= COLS) return false;
211	      if (board[r][c] !== "") return false;
212	    }
213	    return true;
214	  }
215	
216	  function spawn() {
217	    if (next.length === 0) scripted = false;
218	    fillPreview();
219	    var type = next.shift();
220	    fillPreview();
221	    var s = SHAPES[type];
222	    var piece = {
223	      type: type, matrix: s.m.slice(), row: s.row, col: s.col,
224	      lockTicks: 0,   // consecutive gravity steps spent unable to fall
225	      lockResets: 0   // lifetime count of lock-delay restarts
226	    };
227	    if (!fits(piece.matrix, piece.row, piece.col)) {
228	      current = null;
229	      status = "gameover";
230	      stopTimer();
231	      return;
232	    }
233	    current = piece;
234	  }
235	
236	  function lock() {
237	    var cells = shapeCells(current.matrix, current.row, current.col);
238	    for (var i = 0; i < cells.length; i++) {
239	      board[cells[i][0]][cells[i][1]] = current.type;
240	    }
241	    current = null;
242	    clearLines();
243	    spawn();
244	  }
245	
246	  // Removes every full row; rows above drop down.
247	  function clearLines() {
248	    var kept = board.filter(function (row) {
249	      return row.some(function (v) { return v === ""; });
250	    });
251	    var cleared = ROWS - kept.length;
252	    if (cleared === 0) return;
253	    while (kept.length < ROWS) kept.unshift(emptyBoard()[0]);
254	    board = kept;
255	    lines += cleared;
256	    score += CLEAR_POINTS[Math.min(cleared, 4)] * level;
257	  }
258	
259	  function tryMove(dr, dc) {
260	    if (!current) return false;
261	    if (!fits(current.matrix, current.row + dr, current.col + dc)) return false;
262	    current.row += dr;
263	    current.col += dc;
264	    return true;
265	  }
266	
267	  // The single gravity step, used by the real timer and tick().
268	  // A step that cannot move the piece down counts one tick of lock delay.
269	  // Returns true if the piece moved down.
270	  function gravityStep() {
271	    if (status !== "running" || !current) return false;
272	    if (tryMove(1, 0)) {
273	      current.lockTicks = 0;
274	      return true;
275	    }
276	    current.lockTicks++;
277	    if (current.lockTicks >= LOCK_DELAY_TICKS) lock();
278	    return false;
279	  }
280	
281	  // Restarts a running lock delay, up to MAX_LOCK_RESETS times per piece.
282	  function restartLockDelay() {
283	    if (current.lockTicks > 0 && current.lockResets < MAX_LOCK_RESETS) {
284	      current.lockResets++;
285	      current.lockTicks = 0;
286	    }
287	  }
288	
289	  // Soft drop. If the piece cannot fall, it counts like a sideways move:
290	  // it restarts a running lock delay and never adds a lock tick itself.
291	  function softDrop() {
292	    if (tryMove(1, 0)) {
293	      current.lockTicks = 0;
294	      score += SOFT_DROP_POINTS;
295	    } else {
296	      restartLockDelay();
297	    }
298	  }
299	
300	  // Left/right. A move made while the lock delay is running restarts it.
301	  function shift(dc) {
302	    if (tryMove(0, dc)) restartLockDelay();
303	  }
304	
305	  // Clockwise rotation. Tries the rotated shape in place, then shifted
306	  // sideways; if none fit, the piece is left unchanged.
307	  function rotateCW() {
308	    if (!current) return;
309	    var m = current.matrix;
310	    var n = m.length;
311	    var rotated = [];
312	    for (var r = 0; r < n; r++) {
313	      var line = "";
314	      for (var c = 0; c < n; c++) line += m[n - 1 - c][r];
315	      rotated.push(line);
316	    }
317	    var kicks = [0, -1, 1, -2, 2];
318	    for (var i = 0; i < kicks.length; i++) {
319	      var nc = current.col + kicks[i];
320	      if (fits(rotated, current.row, nc)) {
321	        current.matrix = rotated;
322	        current.col = nc;
323	        return;
324	      }
325	    }
326	  }
327	
328	  // Hard drop skips the lock delay.
329	  function hardDrop() {
330	    if (!current) return;
331	    while (tryMove(1, 0)) score += HARD_DROP_POINTS;
332	    lock();
333	  }
334	
335	  function applyInput(action) {
336	    if (status !== "running" || !current) return;
337	    switch (action) {
338	      case "left": shift(-1); break;
339	      case "right": shift(1); break;
340	      case "softDrop": softDrop(); break;
341	      case "hardDrop": hardDrop(); break;
342	      case "rotateCW":
343	      case "rotate": rotateCW(); break;
344	    }
345	  }
346	
347	  // ---- Timer ----
348	  function stopTimer() {
349	    if (timer !== null) { clearInterval(timer); timer = null; }
350	  }
351	
352	  function startTimer() {
353	    stopTimer();
354	    timer = setInterval(function () {
355	      gravityStep();
356	      render();
357	    }, GRAVITY_MS);
358	  }
359	
360	  // ---- Rendering (synchronous) ----
361	  var boardEl = document.getElementById("board");
362	  var nextEl = document.getElementById("next");
363	  var boardWrapEl = boardEl.parentNode;
364	  var overlayEl = document.createElement("div");
365	  overlayEl.className = "overlay";
366	  overlayEl.setAttribute("data-testid", "game-over");
367	  overlayEl.textContent = "Game over";
368	  var scoreEl = document.getElementById("score");
369	  var levelEl = document.getElementById("level");
370	  var linesEl = document.getElementById("lines");
371	  var cellEls = [];
372	
373	  (function buildBoard() {
374	    for (var r = 0; r < ROWS; r++) {
375	      cellEls.push([]);
376	      for (var c = 0; c < COLS; c++) {
377	        var el = document.createElement("div");
378	        el.className = "cell";
379	        el.setAttribute("data-testid", "cell");
380	        el.setAttribute("data-row", String(r));
381	        el.setAttribute("data-col", String(c));
382	        el.setAttribute("data-filled", "false");
383	        el.setAttribute("data-piece", "");
384	        boardEl.appendChild(el);
385	        cellEls[r].push(el);
386	      }
387	    }
388	  })();
389	
390	  function paintCell(el, piece) {
391	    el.className = piece ? "cell p-" + piece : "cell";
392	    el.setAttribute("data-filled", piece ? "true" : "false");
393	    el.setAttribute("data-piece", piece);
394	  }
395	
396	  function renderNext() {
397	    nextEl.textContent = "";
398	    for (var i = 0; i < Math.min(next.length, PREVIEW); i++) {
399	      var type = next[i];
400	      var m = SHAPES[type].m;
401	      var offset = type === "I" ? 1 : 0; // I's filled row is row 1 of its matrix
402	      var mini = document.createElement("div");
403	      mini.className = "mini";
404	      mini.setAttribute("data-testid", "next-piece-item");
405	      mini.setAttribute("data-piece", type);
406	      for (var r = 0; r < 2; r++) {
407	        for (var c = 0; c < 4; c++) {
408	          var ch = m[r + offset] && m[r + offset][c];
409	          var cell = document.createElement("div");
410	          cell.className = ch && ch !== "." ? "mini-cell p-" + type : "mini-cell";
411	          mini.appendChild(cell);
412	        }
413	      }
414	      nextEl.appendChild(mini);
415	    }
416	  }
417	
418	  function render() {
419	    var view = board.map(function (row) { return row.slice(); });
420	    if (current) {
421	      var cells = shapeCells(current.matrix, current.row, current.col);
422	      for (var i = 0; i < cells.length; i++) {
423	        view[cells[i][0]][cells[i][1]] = current.type;
424	      }
425	    }
426	    for (var r = 0; r < ROWS; r++) {
427	      for (var c = 0; c < COLS; c++) paintCell(cellEls[r][c], view[r][c]);
428	    }
429	    scoreEl.textContent = String(score);
430	    levelEl.textContent = String(level);
431	    linesEl.textContent = String(lines);
432	    // The overlay is in the DOM only while the game is over.
433	    if (status === "gameover") {
434	      if (!overlayEl.parentNode) boardWrapEl.appendChild(overlayEl);
435	    } else if (overlayEl.parentNode) {
436	      overlayEl.parentNode.removeChild(overlayEl);
437	    }
438	    renderNext();
439	  }
440	
441	  // ---- Game control ----
442	  function validTypes(queue) {
443	    if (!Array.isArray(queue)) return [];
444	    return queue.filter(function (t) { return SHAPES.hasOwnProperty(t); });
445	  }
446	
447	  function newGame(queue) {
448	    board = emptyBoard();
449	    score = 0;
450	    level = 1;
451	    lines = 0;
452	    status = "running";
453	    current = null;
454	    bag = [];
455	    if (Array.isArray(queue)) {
456	      next = validTypes(queue);
457	      scripted = true;
458	    } else {
459	      next = [];
460	      scripted = false;
461	    }
462	    spawn();
463	    startTimer();
464	    render();
465	  }
466	
467	  function setQueue(queue) {
468	    next = validTypes(queue);
469	    scripted = true;
470	    render();
471	  }
472	
473	  function setBoard(rows) {
474	    var b = emptyBoard();
475	    for (var r = 0; r < ROWS; r++) {
476	      var line = (rows && rows[r]) || "";
477	      for (var c = 0; c < COLS; c++) {
478	        var ch = line.charAt(c);
479	        b[r][c] = SHAPES.hasOwnProperty(ch) ? ch : "";
480	      }
481	    }
482	    board = b;
483	    render();
484	  }
485	
486	  function getBoard() {
487	    return board.map(function (row) {
488	      return row.map(function (v) { return v || "."; }).join("");
489	    });
490	  }
491	
492	  function getState() {
493	    var cur = null;
494	    if (current) {
495	      var cells = shapeCells(current.matrix, current.row, current.col);
496	      cells.sort(function (a, b) { return a[0] - b[0] || a[1] - b[1]; });
497	      cur = { type: current.type, cells: cells };
498	    }
499	    return {
500	      current: cur,
501	      next: next.slice(),
502	      score: score,
503	      level: level,
504	      lines: lines,
505	      status: status
506	    };
507	  }
508	
509	  function tick(n) {
510	    var steps = n === undefined ? 1 : Math.max(0, Math.floor(Number(n)) || 0);
511	    for (var i = 0; i < steps; i++) gravityStep();
512	    render();
513	  }
514	
515	  window.__tetris = {
516	    newGame: newGame,
517	    setQueue: setQueue,
518	    setBoard: setBoard,
519	    tick: tick,
520	    input: function (action) { applyInput(action); render(); },
521	    getBoard: getBoard,
522	    getState: getState
523	  };
524	
525	  // ---- Keyboard ----
526	  var KEYS = {
527	    ArrowLeft: "left",
528	    ArrowRight: "right",
529	    ArrowDown: "softDrop",
530	    " ": "hardDrop",
531	    ArrowUp: "rotateCW"
532	  };
533	
534	  document.addEventListener("keydown", function (e) {
535	    var action = KEYS[e.key];
536	    if (!action) return;
537	    e.preventDefault();
538	    window.__tetris.input(action);
539	  });
540	
541	  document.getElementById("new-game").addEventListener("click", function (e) {
542	    e.currentTarget.blur();
543	    newGame();
544	  });
545	
546	  newGame();
547	})();
548	</script>
549	</body>
550	</html>

