132	<script>
133	(function () {
134	  "use strict";
135	
136	  var ROWS = 20;
137	  var COLS = 10;
138	  var TYPES = ["I", "O", "T", "S", "Z", "J", "L"];
139	  var PREVIEW = 1;
140	  var GRAVITY_MS = 1000;
141	  var LOCK_DELAY_TICKS = 2;   // gravity steps a piece may spend unable to fall
142	  var MAX_LOCK_RESETS = 3;    // times per piece a sideways move or soft drop restarts the delay
143	
144	  // Points for rows cleared at once, times the level. Clearing rows together
145	  // must always beat clearing the same rows one at a time.
146	  var CLEAR_POINTS = [0, 100, 300, 500, 800];
147	  var SOFT_DROP_POINTS = 1;   // per cell moved down by soft drop
148	  var HARD_DROP_POINTS = 2;   // per cell dropped by hard drop
149	
150	  // Each shape is a square matrix; spawn puts its filled cells in rows 0-1.
151	  var SHAPES = {
152	    I: { m: ["....", "IIII", "....", "...."], row: -1, col: 3 },
153	    O: { m: ["OO", "OO"], row: 0, col: 4 },
154	    T: { m: [".T.", "TTT", "..."], row: 0, col: 3 },
155	    S: { m: [".SS", "SS.", "..."], row: 0, col: 3 },
156	    Z: { m: ["ZZ.", ".ZZ", "..."], row: 0, col: 3 },
157	    J: { m: ["J..", "JJJ", "..."], row: 0, col: 3 },
158	    L: { m: ["..L", "LLL", "..."], row: 0, col: 3 }
159	  };
160	
161	  // ---- State ----
162	  var board;        // board[row][col] = "" or piece letter
163	  var current;      // { type, matrix, row, col, lockTicks, lockResets } or null
164	  var next;         // upcoming piece letters, soonest first
165	  var scripted;     // true while `next` comes from a test-supplied queue
166	  var bag = [];
167	  var score, level, lines, status;
168	  var timer = null;
169	
170	  function emptyBoard() {
171	    var b = [];
172	    for (var r = 0; r < ROWS; r++) {
173	      var row = [];
174	      for (var c = 0; c < COLS; c++) row.push("");
175	      b.push(row);
176	    }
177	    return b;
178	  }
179	
180	  function randomType() {
181	    if (bag.length === 0) {
182	      bag = TYPES.slice();
183	      for (var i = bag.length - 1; i > 0; i--) {
184	        var j = Math.floor(Math.random() * (i + 1));
185	        var t = bag[i]; bag[i] = bag[j]; bag[j] = t;
186	      }
187	    }
188	    return bag.pop();
189	  }
190	
191	  function fillPreview() {
192	    if (scripted) return;
193	    while (next.length < PREVIEW) next.push(randomType());
194	  }
195	
196	  function shapeCells(matrix, row, col) {
197	    var cells = [];
198	    for (var r = 0; r < matrix.length; r++) {
199	      for (var c = 0; c < matrix[r].length; c++) {
200	        if (matrix[r][c] !== ".") cells.push([row + r, col + c]);
201	      }
202	    }
203	    return cells;
204	  }
205	
206	  function fits(matrix, row, col) {
207	    var cells = shapeCells(matrix, row, col);
208	    for (var i = 0; i < cells.length; i++) {
209	      var r = cells[i][0], c = cells[i][1];
210	      if (r < 0 || r >= ROWS || c < 0 || c >= COLS) return false;
211	      if (board[r][c] !== "") return false;
212	    }
213	    return true;
214	  }
215	
216	  function spawn() {
217	    if (next.length === 0) scripted = false;
218	    fillPreview();
219	    var type = next.shift();
220	    fillPreview();
221	    var s = SHAPES[type];
222	    var piece = {
223	      type: type, matrix: s.m.slice(), row: s.row, col: s.col,
224	      lockTicks: 0,   // consecutive gravity steps spent unable to fall
225	      lockResets: 0   // lifetime count of lock-delay restarts
226	    };
227	    if (!fits(piece.matrix, piece.row, piece.col)) {
228	      current = null;
229	      status = "gameover";
230	      stopTimer();
231	      return;
232	    }
233	    current = piece;
234	  }
235	
236	  function lock() {
237	    var cells = shapeCells(current.matrix, current.row, current.col);
238	    for (var i = 0; i < cells.length; i++) {
239	      board[cells[i][0]][cells[i][1]] = current.type;
240	    }
241	    current = null;
242	    clearLines();
243	    spawn();
244	  }
245	
246	  // Removes every full row; rows above drop down.
247	  function clearLines() {
248	    var kept = board.filter(function (row) {
249	      return row.some(function (v) { return v === ""; });
250	    });
251	    var cleared = ROWS - kept.length;
252	    if (cleared === 0) return;
253	    while (kept.length < ROWS) kept.unshift(emptyBoard()[0]);
254	    board = kept;
255	    lines += cleared;
256	    score += CLEAR_POINTS[Math.min(cleared, 4)] * level;
257	  }
258	
259	  function tryMove(dr, dc) {
260	    if (!current) return false;
261	    if (!fits(current.matrix, current.row + dr, current.col + dc)) return false;
262	    current.row += dr;
263	    current.col += dc;
264	    return true;
265	  }
266	
267	  // The single gravity step, used by the real timer and tick().
268	  // A step that cannot move the piece down counts one tick of lock delay.
269	  // Returns true if the piece moved down.
270	  function gravityStep() {
271	    if (status !== "running" || !current) return false;
272	    if (tryMove(1, 0)) {
273	      current.lockTicks = 0;
274	      return true;
275	    }
276	    current.lockTicks++;
277	    if (current.lockTicks >= LOCK_DELAY_TICKS) lock();
278	    return false;
279	  }
280	
281	  // Restarts a running lock delay, up to MAX_LOCK_RESETS times per piece.
282	  function restartLockDelay() {
283	    if (current.lockTicks > 0 && current.lockResets < MAX_LOCK_RESETS) {
284	      current.lockResets++;
285	      current.lockTicks = 0;
286	    }
287	  }
288	
289	  // Soft drop. If the piece cannot fall, it counts like a sideways move:
290	  // it restarts a running lock delay and never adds a lock tick itself.
291	  function softDrop() {
292	    if (tryMove(1, 0)) {
293	      current.lockTicks = 0;
294	      score += SOFT_DROP_POINTS;
295	    } else {
296	      restartLockDelay();
297	    }
298	  }
299	
300	  // Left/right. A move made while the lock delay is running restarts it.
301	  function shift(dc) {
302	    if (tryMove(0, dc)) restartLockDelay();
303	  }
304	
305	  // Clockwise rotation. Tries the rotated shape in place, then shifted
306	  // sideways; if none fit, the piece is left unchanged.
307	  function rotateCW() {
308	    if (!current) return;
309	    var m = current.matrix;
310	    var n = m.length;
311	    var rotated = [];
312	    for (var r = 0; r < n; r++) {
313	      var line = "";
314	      for (var c = 0; c < n; c++) line += m[n - 1 - c][r];
315	      rotated.push(line);
316	    }
317	    var kicks = [0, -1, 1, -2, 2];
318	    for (var i = 0; i < kicks.length; i++) {
319	      var nc = current.col + kicks[i];
320	      if (fits(rotated, current.row, nc)) {
321	        current.matrix = rotated;
322	        current.col = nc;
323	        return;
324	      }
325	    }
326	  }
327	
328	  // Hard drop skips the lock delay.
329	  function hardDrop() {
330	    if (!current) return;
331	    while (tryMove(1, 0)) score += HARD_DROP_POINTS;
332	    lock();
333	  }
334	
335	  function applyInput(action) {
336	    if (status !== "running" || !current) return;
337	    switch (action) {
338	      case "left": shift(-1); break;
339	      case "right": shift(1); break;
340	      case "softDrop": softDrop(); break;
341	      case "hardDrop": hardDrop(); break;
342	      case "rotateCW":
343	      case "rotate": rotateCW(); break;
344	    }
345	  }
346	
347	  // ---- Timer ----
348	  function stopTimer() {
349	    if (timer !== null) { clearInterval(timer); timer = null; }
350	  }
351	
352	  function startTimer() {
353	    stopTimer();
354	    timer = setInterval(function () {
355	      gravityStep();
356	      render();
357	    }, GRAVITY_MS);
358	  }
359	
360	  // ---- Rendering (synchronous) ----
361	  var boardEl = document.getElementById("board");
362	  var nextEl = document.getElementById("next");
363	  var boardWrapEl = boardEl.parentNode;
364	  var overlayEl = document.createElement("div");
