412	        }
413	      }
414	      nextEl.appendChild(mini);
415	    }
416	  }
417	
418	  function render() {
419	    var view = board.map(function (row) { return row.slice(); });
420	    if (current) {
421	      var cells = shapeCells(current.matrix, current.row, current.col);
422	      for (var i = 0; i < cells.length; i++) {
