434	      if (!overlayEl.parentNode) boardWrapEl.appendChild(overlayEl);
435	    } else if (overlayEl.parentNode) {
436	      overlayEl.parentNode.removeChild(overlayEl);
437	    }
438	    renderNext();
439	  }
440	
441	  // ---- Game control ----
442	  function validTypes(queue) {
443	    if (!Array.isArray(queue)) return [];
444	    return queue.filter(function (t) { return SHAPES.hasOwnProperty(t); });
445	  }
446	
447	  function newGame(queue) {
448	    board = emptyBoard();
449	    score = 0;
450	    level = 1;
451	    lines = 0;
452	    status = "running";
453	    current = null;
454	    bag = [];
